source_context:
 1: - set_fact:
 2:     pv_mount_directory: /tmp/{{ volume_name }}
 3:     pv_definition_file: /tmp/{{ volume_name }}-def.yml
 4: 
 5: - name: Create internal mount directory
 6:   shell: |
 7:     mkdir -p {{ pv_mount_directory }}
 8:     chmod -R 777 {{ pv_mount_directory }}
 9:     chmod -R a+w {{ pv_mount_directory }}
10:     chcon -Rt svirt_sandbox_file_t {{ pv_mount_directory }}
11:   ignore_errors: true
12: 
13: - name: Copy pv file to master
14:   template:
15:     src: "pv.yml.j2"
16:     dest: "{{ pv_definition_file }}"
17: 
18: - name: Create pv {{ pv_name }}
19:   command: "kubectl apply -f {{ pv_definition_file }}"
